#include <bits/stdc++.h>
using namespace std;
int lcs(const string& a, const string& b){
    int n=a.size(), m=b.size();
    vector<vector<int>> dp(n+1, vector<int>(m+1,0));
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++)
        dp[i][j] = a[i-1]==b[j-1] ? dp[i-1][j-1]+1 : max(dp[i-1][j], dp[i][j-1]);
    return dp[n][m];
}
void msort(vector<int>& v, int l, int r, vector<int>& t){ // sorts [l,r)
    if(r-l<=1) return;
    int m=(l+r)/2; msort(v,l,m,t); msort(v,m,r,t);
    int i=l,j=m,k=l;
    while(i<m && j<r) t[k++] = (v[i]<=v[j]) ? v[i++] : v[j++];
    while(i<m) t[k++]=v[i++];
    while(j<r) t[k++]=v[j++];
    for(int x=l;x<r;x++) v[x]=t[x];
}
int main(){
    string a,b; int n; cin>>a>>b>>n;
    vector<int> v(n), t(n); for(auto& x:v) cin>>x;
    cout<<lcs(a,b)<<"\n";
    msort(v,0,n,t); for(int x:v) cout<<x<<" "; cout<<"\n";
}

