bool wordBreak(const string& s, const vector<string>& words){
    unordered_set<string> dict(words.begin(), words.end());
    size_t L=0; for(auto& w:words) L=max(L,w.size());
    int n=s.size(); vector<char> dp(n+1,0); dp[0]=1;
    for(int i=1;i<=n;i++)
        for(int len=1; len<=(int)L && len<=i && !dp[i]; len++)
            if(dp[i-len] && dict.count(s.substr(i-len,len))) dp[i]=1;
    return dp[n];
}
int main(){
    string s; int k; cin>>s>>k; vector<string> w(k); for(auto& x:w) cin>>x;
    cout<<(wordBreak(s,w) ? "true" : "false")<<"\n";
}

