int main(){
    long long n; cin>>n; const long long MOD=1e9+7;
    vector<vector<int>> adj={{1},{0,2},{0,1,3,4},{2,4},{0}}; // a e i o u
    if(n==1){ cout<<5<<"\n"; return 0; }
    long long dp[5][2]={};                  // [vowel][0=last up,1=last down]
    for(int u=0;u<5;u++) for(int v:adj[u]) dp[v][v>u?0:1]++;
    for(long long len=3; len<=n; len++){
        long long nd[5][2]={};
