                int nd_dir = v>u?0:1;
                if(nd_dir==d) continue;     // must alternate
                nd[v][nd_dir]=(nd[v][nd_dir]+dp[u][d])%MOD;
            }
        memcpy(dp,nd,sizeof dp);
    }
    long long ans=0; for(int u=0;u<5;u++) ans=(ans+dp[u][0]+dp[u][1])%MOD;
    cout<<ans<<"\n";
}

