#include <bits/stdc++.h>
using namespace std;
int main(){
    long long N,M; int K; cin>>N>>M>>K; const long long MOD=1e9+7;
    long long E=M/2%MOD, O=(M-M/2)%MOD;
    if(K>N-1){ cout<<0<<"\n"; return 0; }
    vector<array<long long,2>> dp(K+2, {0,0});   // [k][0=even last,1=odd last]
    dp[0]={E,O};
    for(long long i=2;i<=N;i++){
        vector<array<long long,2>> nd(K+2, {0,0});
        for(int k=0;k<=K;k++){
            long long ev=dp[k][0], od=dp[k][1];
            nd[k+1][0]=(nd[k+1][0]+ev*E)%MOD;         // even after even
            nd[k][0]=(nd[k][0]+od*E)%MOD;             // even after odd
            nd[k][1]=(nd[k][1]+(ev+od)%MOD*O)%MOD;    // odd after any
        }
        dp=nd;
    }
    cout<<(dp[K][0]+dp[K][1])%MOD<<"\n";
}

