long long divs(long long x){
    long long c=0;
    for(long long i=1;i*i<=x;i++) if(x%i==0) c+= (i*i==x)?1:2;
    return c;
}
int main(){
    int n; cin>>n; vector<long long> a(n); for(auto& x:a) cin>>x;
    unordered_map<long long,long long> best; long long ans=0;
    for(long long x:a){
        vector<long long> preds={x-1, x+1, 2*x, 3*x};
        if(x%2==0) preds.push_back(x/2);
        if(x%3==0) preds.push_back(x/3);
        long long p=0;
        for(long long y:preds){ auto it=best.find(y); if(it!=best.end()) p=max(p,it->second); }
        long long cur=divs(x)+p;
        best[x]=max(best[x], cur); ans=max(ans, cur);
    }
    cout<<ans<<"\n";
}

