int main(){
    int n,K; cin>>n>>K; vector<long long> a(n+1); for(int i=1;i<=n;i++) cin>>a[i];
    const long long INF=LLONG_MAX/4;
    // dp[i][k]: first i items split into k+1 segments
    vector<vector<long long>> dp(n+1, vector<long long>(K+1, INF));
    for(int i=1;i<=n;i++){
        long long mx=0, sum=0;
        for(int j=i;j>=1;j--){                 // last segment = j..i
            mx=max(mx,a[j]); sum+=a[j];
            long long cost=mx*(i-j+1)-sum;
            if(j==1){ for(int k=0;k<=K;k++) dp[i][k]=min(dp[i][k], cost); }
            else for(int k=1;k<=K;k++)
                if(dp[j-1][k-1]<INF) dp[i][k]=min(dp[i][k], dp[j-1][k-1]+cost);
        }
    }
    cout<<dp[n][K]<<"\n";
}

