int main(){
    int n,K; cin>>n>>K; vector<int> a(n); for(auto& x:a) cin>>x;
    vector<int> v=a; sort(v.begin(),v.end()); v.erase(unique(v.begin(),v.end()),v.end());
    for(auto& x:a) x=lower_bound(v.begin(),v.end(),x)-v.begin();   // compress
    vector<vector<int>> mode(n, vector<int>(n));
    for(int l=0;l<n;l++){
        vector<int> f(v.size(),0); int best=0;
        for(int r=l;r<n;r++){ best=max(best, ++f[a[r]]); mode[l][r]=best; }
    }
    const int NEG=INT_MIN/2;
    // dp[g][i]: max score splitting first i elements into g groups
    vector<vector<int>> dp(K+1, vector<int>(n+1, NEG)); dp[0][0]=0;
    for(int g=1;g<=K;g++)
        for(int i=g;i<=n;i++)
            for(int j=g-1;j<i;j++)               // last group = a[j..i-1]
                if(dp[g-1][j]>NEG) dp[g][i]=max(dp[g][i], dp[g-1][j]+mode[j][i-1]);
    cout<<(K<=n ? dp[K][n] : -1)<<"\n";
}
